	/* @Override */
	protected void createProgram(Language lang, CompilerSpec cSpec)
    {
		base.createProgram(lang, cSpec);
		api.getState().setCurrentProgram(program);
	}

	protected SchemaContext buildContext() {
		return new ToySchemaBuilder()
				.noRegisterGroups()
				.useRegistersPerFrame()
				.build();
	}

	protected TraceThread createTraceWithThreadAndStack(bool open)
    {
		if (open) {
			createAndOpenTrace();
		}
		else {
			createTrace();
		}
		TraceThread thread;
		using (Transaction _ = tb.startTransaction())
{
			tb.createRootObject(buildContext(), "Target");
			thread = tb.getOrAddThread("Threads[0]", 0);
			tb.createObjectsFramesAndRegs(thread, Lifespan.nowOn(0), tb.host, 3);
		}
		waitForSwing();
		return thread;
	}

	protected void createTraceWithBinText()
    {
		createAndOpenTrace();

		using (Transaction _ = tb.startTransaction())
{
			tb.createRootObject(buildContext(), "Target");
			DBTraceMemoryManager mm = tb.trace.getMemoryManager();
			mm.createRegion("Memory[bin.text]", 0, tb.range(0x00400000, 0x0040ffff),
				Set.of(TraceMemoryFlag.READ, TraceMemoryFlag.EXECUTE));

			mm.putBytes(0, tb.addr(0x00400000), tb.buf(1, 2, 3, 4, 5, 6, 7, 8));
		}
		traceManager.activateTrace(tb.trace);
		waitForSwing();
	}

	protected void createMappedTraceAndProgram()
    {
		createAndOpenTrace();
		createProgramFromTrace();

		intoProject(program);
		intoProject(tb.trace);

		programManager.openProgram(program);
		traceManager.activateTrace(tb.trace);

		using (Transaction _ = program.openTransaction("add block"))
{
			program.getMemory()
					.createInitializedBlock(".text", addr(program, 0x00400000), 4096, (byte) 0,
						monitor, false);
		}

		CompletableFuture<Void> changesSettled;
		using (Transaction _ = tb.startTransaction())
{
			tb.createRootObject(buildContext(), "Target");
			tb.trace.getMemoryManager()
					.createRegion("Memory[bin.text]", 0, tb.range(0x00400000, 0x00400fff),
						Set.of(TraceMemoryFlag.READ, TraceMemoryFlag.EXECUTE));
			changesSettled = mappingService.changesSettled();
			mappingService.addIdentityMapping(tb.trace, program, Lifespan.nowOn(0), true);
		}
		waitForSwing();
		waitOn(changesSettled);
	}

	protected Address createEmulatableProgram()
    {
		createProgram();
		programManager.openProgram(program);

		Address entry = addr(program, 0x00400000);
		using (Transaction _ = program.openTransaction("init"))
{
			program.getMemory()
					.createInitializedBlock(".text", entry, 4096, (byte) 0,
						monitor, false);
			Assembler asm = Assemblers.getAssembler(program);
			asm.assemble(entry, "imm r0,#123");
		}

		// Emulate launch will create a static mapping
		intoProject(program);

		return entry;
	}

